import{_ as p,a0 as n,w as i,s as d,I as s,x as a,a1 as l,A as r,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"如何在 Linux 上用 SQL 语句来查询 Apache 日志 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上用 SQL 语句来查询 Apache 日志 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上用 SQL 语句来查询 Apache 日志 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上用 SQL 语句来查询 Apache 日志 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141030 How to run SQL queries against Apache log files on Linux","title":"如何在 Linux 上用 SQL 语句来查询 Apache 日志","tag":"201412","desc":""},"relativePath":"201412/20141030 How to run SQL queries against Apache log files on Linux.md","filePath":"[post].md"}'),c={name:"201412/20141030 How to run SQL queries against Apache log files on Linux.md"};function u(g,e,m,h,f,q){const t=n("Link");return i(),d("div",null,[e[19]||(e[19]=s("h1",{id:"如何在-linux-上用-sql-语句来查询-apache-日志",tabindex:"-1"},[a("如何在 Linux 上用 SQL 语句来查询 Apache 日志 "),s("a",{class:"header-anchor",href:"#如何在-linux-上用-sql-语句来查询-apache-日志","aria-label":"Permalink to “如何在 Linux 上用 SQL 语句来查询 Apache 日志”"},"​")],-1)),e[20]||(e[20]=s("p",null,"Linux 有一个显著的特点，在正常情况下，你可以通过日志分析系统日志来了解你的系统中发生了什么，或正在发生什么。的确，系统日志是系统管理员在解决系统和应用问题时最需要的第一手资源。我们将在这篇文章中着重讲解 Apache HTTP web server 生成的 Apache access 日志。",-1)),s("p",null,[e[1]||(e[1]=a("这次，我们会通过另类的途径来分析 Apache access 日志，我们使用的工具是 ",-1)),l(t,{href:"http://www.steve.org.uk/Software/asql/"},{default:r(()=>[...e[0]||(e[0]=[a("asql",-1)])]),_:1}),e[2]||(e[2]=a("。asql 是一个开源的工具，它能够允许使用者使用 SQL 语句来查询日志，从而通过更加友好的格式展现相同的信息。",-1))]),e[21]||(e[21]=o(`<h3 id="apache-日志背景知识" tabindex="-1">Apache 日志背景知识 <a class="header-anchor" href="#apache-日志背景知识" aria-label="Permalink to “Apache 日志背景知识”">​</a></h3><p>Apache 有两种日志：</p><ul><li><strong>Access log</strong>：存放在路径 /var/log/apache2/access.log (Debian) 或者 /var/log/httpd/access_log (Red Hat)。Access Log 记录所有 Apache web server 执行的请求。</li><li><strong>Error log</strong>：存放在路径 /var/log/apache2/error.log (Debian) 或者 /var/log/httpd/error_log (Red Hat)。Error log 记录所有 Apache web server 报告的错误以及错误的情况。Error 情况包括（不限于）403（Forbidden，通常在请求被拒绝访问时被报告），404（Not found，在请求资源不存在时被报告）。</li></ul><p>虽然管理员可以通过配置 Apache 的配置文件来自定义 Apache access log 的详细程度，不过在这篇文章中，我们会使用默认的配置，如下：</p><pre><code>远程 IP - 请求时间 - 请求类型 - 响应代码 - 请求的 URL - 远程的浏览器信息 (也许包含操作系统信息)
</code></pre><p>因此一个典型的 Apache 日志条目就是下面这个样子：</p><pre><code>192.168.0.101 - - [22/Aug/2014:12:03:36 -0300] &quot;GET /icons/unknown.gif HTTP/1.1&quot; 200 519 &quot;http://192.168.0.10/test/projects/read_json/&quot; &quot;Mozilla/5.0 (X11; Ubuntu; Linux x86_64; rv:30.0) Gecko/20100101 Firefox/30.0&quot;
</code></pre><p>但是 Apache error log 又是怎么样的呢？因为 error log 条目主要记录 access log 中特殊的请求（你可以自定义），所以你可以通过 access log 来获得关于错误情况的更多信息（example 5 有更多细节）。</p><p>此外要提前说明的， access log 是系统级别的日志文件。要分析虚拟主机的日志文件，你需要检查它们相应的配置文件（例如： 在 /etc/apache2/sites-available/[virtual host name] 里（Debian））。</p><h3 id="在-linux-上安装-asql" tabindex="-1">在 Linux 上安装 asql <a class="header-anchor" href="#在-linux-上安装-asql" aria-label="Permalink to “在 Linux 上安装 asql”">​</a></h3><p>asql 由 Perl 编写，而且需求以下两个 Perl 模块：SQLite 的 DBI 驱动以及 GNU readline。</p><h3 id="在-debian-ubuntu-以及其衍生发行版上安装-asql" tabindex="-1">在 Debian, Ubuntu 以及其衍生发行版上安装 asql <a class="header-anchor" href="#在-debian-ubuntu-以及其衍生发行版上安装-asql" aria-label="Permalink to “在 Debian, Ubuntu 以及其衍生发行版上安装 asql”">​</a></h3><p>使用基于 Debian 发行版上的 aptitude，asql 以及其依赖会被自动安装。</p><pre><code># aptitude install asql
</code></pre><h3 id="在-fedora-centos-rhel-上安装-asql" tabindex="-1">在 Fedora，CentOS，RHEL 上安装 asql <a class="header-anchor" href="#在-fedora-centos-rhel-上安装-asql" aria-label="Permalink to “在 Fedora，CentOS，RHEL 上安装 asql”">​</a></h3>`,15)),s("p",null,[e[4]||(e[4]=a("在 CentOS 或 RHEL 上，你需要启用 ",-1)),l(t,{href:"http://xmodulo.com/how-to-set-up-epel-repository-on-centos.html"},{default:r(()=>[...e[3]||(e[3]=[a("EPEL repository",-1)])]),_:1}),e[5]||(e[5]=a("，然后运行以下代码。在 Fedora 中，直接运行以下代码：",-1))]),e[22]||(e[22]=o(`<pre><code># sudo yum install perl-DBD-SQLite perl-Term-Readline-Gnu
# wget http://www.steve.org.uk/Software/asql/asql-1.7.tar.gz
# tar xvfvz asql-1.7.tar.gz
# cd asql
# make install
</code></pre><h3 id="asql-是如何工作的" tabindex="-1">asql 是如何工作的？ <a class="header-anchor" href="#asql-是如何工作的" aria-label="Permalink to “asql 是如何工作的？”">​</a></h3><p>从上面代码中的依赖中你就可以看出来，asql 转换未结构化的明文 Apache 日志为结构化的 SQLite 数据库信息。生成的 SQLite 数据库可以接受正常的 SQL 查询语句。数据库可以通过当前以及之前的日志文件生成，其中也包括压缩转换过的日志文件，类似 access.log.X.gz 或者 access_log.old。</p><p>首先，从命令行启动 asql：</p><pre><code># asql
</code></pre><p>你会进入 asql 内置的 shell 交互界面。</p><p><img src="https://farm8.staticflickr.com/7493/15477783969_ebedc61afc_o.png" alt=""></p><p>输入 help 列表可执行的命令：</p><p><img src="https://farm8.staticflickr.com/7471/15478852650_ffed84ddc2_o.png" alt=""></p><p>首先在 asql 中加载所有的 access 日志：</p><pre><code>asql &gt; load &lt;apache-access-logs 的路径&gt;
</code></pre><p>比如在 Debian 下：</p><pre><code>asql &gt; load /var/log/apache2/access.*
</code></pre><p>在 CentOS/RHEL 下：</p><pre><code>asql &gt; load /var/log/httpd/access_log*
</code></pre><p>当 asql 完成对 access 日志的加载后，我们就可以开始数据库查询了。注意一下，加载后生成的数据库是 &quot;temporary&quot; （临时）的，意思就是数据库会在你退出 asql 的时候被清除。如果你想要保留数据库，你必须先将其保存为一个文件。我们会在后面介绍如何这么做（参考 example 3 和 4）。</p><p><img src="https://farm8.staticflickr.com/7489/15044293173_f21e38692b_o.png" alt=""></p><p>生成的数据库有一个名为 logs 的表。输入下面的命令列出 logs 表中提供的域：</p><p><img src="https://farm4.staticflickr.com/3955/15664433685_465e8f47bd_o.png" alt=""></p><p>一个名为 .asql 的隐藏文件，保存于用户的 home 目录下，记录用户在 asql shell 中输入的命令历史。因此你可以使用方向键浏览命令历史，按下 ENTER 来重复执行之前的命令。</p><h3 id="asql-上的示例-sql-查询" tabindex="-1">asql 上的示例 SQL 查询 <a class="header-anchor" href="#asql-上的示例-sql-查询" aria-label="Permalink to “asql 上的示例 SQL 查询”">​</a></h3><p>下面是几个使用 asql 针对 Apache 日志文件运行 SQL 查询的示例：</p><p><strong>Example 1</strong>：列出在 2014 年 10 月中请求的来源 / 时间以及 HTTP 状态码。</p><pre><code>SELECT source, date, status FROM logs WHERE date &gt;= &#39;2014-10-01T00:00:00&#39; ORDER BY source;
</code></pre><p><img src="https://farm8.staticflickr.com/7488/15664433665_dde4ac1319_z.jpg" alt=""></p><p><strong>Example 2</strong>：从小到大显示单个客户端处理的请求大小（bytes）。</p><pre><code>SELECT source, SUM(size), AS NUMBER FROM logs GROUP BY source ORDER BY Number DESC;
</code></pre><p><img src="https://farm4.staticflickr.com/3938/15478271548_369541b56c_z.jpg" alt=""></p><p><strong>Example 3</strong>：在当前目录中保存数据库为 [filename]。</p><pre><code>save [filename]
</code></pre><p><img src="https://farm8.staticflickr.com/7576/15664433645_16510d8938_o.png" alt=""></p><p>这样做可以避免使用 load 命令对日志的语法分析所占用的处理时间。</p><p><strong>Example 4</strong>：在重新进入 asql 后载入数据库。</p><pre><code>restore [filename]
</code></pre><p><img src="https://farm4.staticflickr.com/3941/15664433635_737e714780_o.png" alt=""></p><p><strong>Example 5</strong>：返回 access 日志中记录的 error 情况。在这个例子中，我们将显示所有返回 HTTP 状态码为 403（access forbidden）的请求。</p><pre><code>SELECT source, date, status, request FROM logs WHERE status=&#39;403&#39; ORDER BY date
</code></pre><p><img src="https://farm8.staticflickr.com/7551/15478271518_0444582a3d_z.jpg" alt=""></p><p>这个例子想要表现的是：虽然 asql 只分析 access 日志，我们还是可以通过使用请求的状态域来显示有 error 情况的请求。</p><h3 id="小结" tabindex="-1">小结： <a class="header-anchor" href="#小结" aria-label="Permalink to “小结：”">​</a></h3><p>我们体验了 asql 如何帮助我们分析 Apache 日志文件，并将结果通过友好的格式输出。虽然你也可以通过使用命令行的工具（例如 cat 与 grep，uniq，sort，wc 等等之间的管道）来实现类似功能，与此比较起来 asql 展示了它如同瑞士军刀一般的强大功能，使我们在自己的需求下能够通过标准 SQL 查询语句来过滤日志。</p><p>希望这篇教程能帮助到你们。</p><p>请不要拘束地将评论文章，分享文章，提出疑问。</p><hr>`,44)),s("p",null,[e[7]||(e[7]=a("via: ",-1)),l(t,{href:"http://xmodulo.com/sql-queries-apache-log-files-linux.html"},{default:r(()=>[...e[6]||(e[6]=[a("http://xmodulo.com/sql-queries-apache-log-files-linux.html",-1)])]),_:1})]),s("p",null,[e[11]||(e[11]=a("作者：",-1)),l(t,{href:"http://xmodulo.com/author/gabriel"},{default:r(()=>[...e[8]||(e[8]=[a("Gabriel Cánepa",-1)])]),_:1}),e[12]||(e[12]=a(" 译者：",-1)),l(t,{href:"https://github.com/ThomazL"},{default:r(()=>[...e[9]||(e[9]=[a("ThomazL",-1)])]),_:1}),e[13]||(e[13]=a(" 校对：",-1)),l(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[10]||(e[10]=[a("wxy",-1)])]),_:1})]),s("p",null,[e[16]||(e[16]=a("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[14]||(e[14]=[a("LCTT",-1)])]),_:1}),e[17]||(e[17]=a(" 原创翻译，",-1)),l(t,{href:"http://linux.cn/"},{default:r(()=>[...e[15]||(e[15]=[a("Linux中国",-1)])]),_:1}),e[18]||(e[18]=a(" 荣誉推出",-1))])])}const T=p(c,[["render",u]]);export{b as __pageData,T as default};
